arduino.helper:
// Grove Ultrasonic Ranger: one pin sends a click, then listens for its echo.
long readCm(int pin) {
  pinMode(pin, OUTPUT);
  digitalWrite(pin, LOW);
  delayMicroseconds(2);
  digitalWrite(pin, HIGH);
  delayMicroseconds(5);
  digitalWrite(pin, LOW);
  pinMode(pin, INPUT);
  long us = pulseIn(pin, HIGH, 30000UL);
  return us / 58;
}
